    // Mouse repulsion
    const dx = this.x - mx;
    const dy = this.y - my;
    const dist = Math.hypot(dx, dy);
    if (dist < 90) {
      const force = (90 - dist) / 90;
      this.x += (dx / dist) * force * 7;
      this.y += (dy / dist) * force * 5;
    }
